  if (s.price_change_pct) parts.push(`change prices by ${s.price_change_pct}%`);
  if ((s.customer_churn || []).length) parts.push(`lose ${s.customer_churn.length} customers`);
  return parts.length ? `Scenario: ${parts.join("; ")}.` : "";
}
